fn get_factor(key1: &str, key2: &str, key3: &str, key4: &str, key5: &str, date: &str) -> f64 {
    // Ensure cache is loaded on first call
    load_factor_cache_once();

    // Build the lookup key from non-empty components
    let parts: Vec<&str> = vec![key1, key2, key3, key4, key5]
        .into_iter()
        .filter(|s| !s.is_empty())
        .collect();
    let lookup_key = parts.join("#");

    // O(1) HashMap lookup by key, then small scan for date range
    let result = FACTOR_CACHE.with(|cache| {
        cache.borrow()
            .get(&lookup_key)
            .and_then(|entries| {
                entries.iter()
                    .find(|f| date >= f.start_date.as_str() && date <= f.end_date.as_str())
                    .map(|f| f.value)
            })
            .unwrap_or_else(|| {
                tracing::warn!("Factor not found: {} for date {}", lookup_key, date);
                0.0
            })
    });

    result
}

fn round_cents(amount: f64, rule: &str) -> f64 {
    let scaled = amount * 100.0;
    let rounded = match rule {
        "HALF_UP" => scaled.round(),
        "HALF_DOWN" => {
            let frac = scaled.fract().abs();
            if frac == 0.5 { scaled.trunc() } else { scaled.round() }
        },
        "UP" => scaled.ceil(),
        "DOWN" => scaled.floor(),
        "BANKERS" => {
            let frac = scaled.fract().abs();
            if frac == 0.5 {
                let trunc = scaled.trunc();
                if trunc as i64 % 2 == 0 { trunc } else { trunc + scaled.signum() }
            } else { scaled.round() }
        },
        _ => scaled.round()
    };
    rounded / 100.0
}

