fn get_season(date: &str, summer_start: f64, summer_end: f64) -> String {
    // Extract month from YYYY-MM-DD date format
    let month: u32 = date.split('-').nth(1).and_then(|m| m.parse().ok()).unwrap_or(1);
    let start = summer_start as u32;
    let end = summer_end as u32;
    let is_summer = if start <= end {
        month >= start && month <= end
    } else {
        // Wraparound range (e.g., start=11, end=3)
        month >= start || month <= end
    };
    if is_summer { "SUMMER".to_string() } else { "WINTER".to_string() }
}

fn calculate_tiered(usage: f64, tier1_limit: f64, tier1_rate: f64, tier2_rate: f64) -> f64 {
    if usage <= tier1_limit {
        usage * tier1_rate
    } else {
        (tier1_limit * tier1_rate) + ((usage - tier1_limit) * tier2_rate)
    }
}

fn round_decimals(value: f64, decimals: f64) -> f64 {
    let multiplier = 10_f64.powf(decimals);
    (value * multiplier).round() / multiplier
}

fn add_years(date: &str, years: f64) -> String {
    use chrono::{NaiveDate, Datelike};
    match NaiveDate::parse_from_str(date, "%Y-%m-%d") {
        Ok(d) => {
            let new_year = d.year() + years as i32;
            NaiveDate::from_ymd_opt(new_year, d.month(), d.day())
                .or_else(|| NaiveDate::from_ymd_opt(new_year, d.month(), 28))
                .map(|nd| nd.format("%Y-%m-%d").to_string())
                .unwrap_or_else(|| date.to_string())
        }
        Err(_) => date.to_string(),
    }
}

fn add_months(date: &str, months: f64) -> String {
    use chrono::{NaiveDate, Datelike};
    match NaiveDate::parse_from_str(date, "%Y-%m-%d") {
        Ok(d) => {
            let total = (d.year() as i32) * 12 + (d.month() as i32 - 1) + months as i32;
            let new_year = total.div_euclid(12);
            let new_month = (total.rem_euclid(12) + 1) as u32;
            NaiveDate::from_ymd_opt(new_year, new_month, d.day())
                .or_else(|| NaiveDate::from_ymd_opt(new_year, new_month, 28))
                .map(|nd| nd.format("%Y-%m-%d").to_string())
                .unwrap_or_else(|| date.to_string())
        }
        Err(_) => date.to_string(),
    }
}

fn calculate_tiered_n(usage: f64, tiers_json: &str) -> f64 {
    // Parse tiers from JSON string: [{"limit":500,"rate":0.05},{"limit":1000,"rate":0.08},{"limit":0,"rate":0.12}]
    let tiers: Vec<serde_json::Value> = serde_json::from_str(tiers_json).unwrap_or_default();
    let mut remaining = usage;
    let mut total = 0.0;
    let mut prev_limit = 0.0;

    for tier in &tiers {
        if remaining <= 0.0 { break; }
        let limit = tier["limit"].as_f64().unwrap_or(0.0);
        let rate = tier["rate"].as_f64().unwrap_or(0.0);
        let tier_usage = if limit == 0.0 {
            remaining  // Last tier: unlimited
        } else {
            let tier_size = limit - prev_limit;
            if remaining > tier_size { tier_size } else { remaining }
        };
        total += tier_usage * rate;
        remaining -= tier_usage;
        prev_limit = limit;
    }
    total
}

fn get_tou_period(datetime: &str, schedule_json: &str) -> String {
    // Extract hour from datetime (supports "YYYY-MM-DD HH:MM" or just "HH" or "HH:MM")
    let hour: u32 = if datetime.contains(' ') {
        datetime.split(' ').nth(1).and_then(|t| t.split(':').next()).and_then(|h| h.parse().ok()).unwrap_or(0)
    } else if datetime.contains(':') {
        datetime.split(':').next().and_then(|h| h.parse().ok()).unwrap_or(0)
    } else {
        datetime.parse().unwrap_or(0)
    };
    let periods: Vec<serde_json::Value> = serde_json::from_str(schedule_json).unwrap_or_default();
    for p in &periods {
        let start = p["start"].as_u64().unwrap_or(0) as u32;
        let end = p["end"].as_u64().unwrap_or(24) as u32;
        if (start <= end && hour >= start && hour < end) || (start > end && (hour >= start || hour < end)) {
            return p["period"].as_str().unwrap_or("OFF_PEAK").to_string();
        }
    }
    "OFF_PEAK".to_string()
}

fn clamp_f64(value: f64, min_val: f64, max_val: f64) -> f64 {
    if value < min_val { min_val } else if value > max_val { max_val } else { value }
}

fn calculate_ratchet(current_demand: f64, history_json: &str, ratchet_pct: f64) -> f64 {
    let history: Vec<f64> = serde_json::from_str(history_json).unwrap_or_default();
    let peak_history = history.iter().cloned().fold(0.0_f64, f64::max);
    let ratchet_floor = peak_history * ratchet_pct;
    if current_demand > ratchet_floor { current_demand } else { ratchet_floor }
}

fn power_factor_adj(demand_charge: f64, actual_pf: f64, target_pf: f64) -> f64 {
    // No adjustment for missing/invalid PF or when at/above target
    if actual_pf <= 0.0 || target_pf <= 0.0 || actual_pf >= target_pf {
        demand_charge
    } else {
        demand_charge * (target_pf / actual_pf)
    }
}

fn is_event_day(date: &str, events_json: &str) -> f64 {
    let events: Vec<String> = serde_json::from_str(events_json).unwrap_or_default();
    if events.iter().any(|e| e == date) { 1.0 } else { 0.0 }
}

fn get_day_type(date: &str) -> String {
    use chrono::{NaiveDate, Datelike, Weekday};
    match NaiveDate::parse_from_str(date, "%Y-%m-%d") {
        Ok(d) => match d.weekday() {
            Weekday::Sat | Weekday::Sun => "WEEKEND".to_string(),
            _ => "WEEKDAY".to_string(),
        },
        Err(_) => "WEEKDAY".to_string(),
    }
}
